<script setup>
import { computed, onMounted, ref, inject, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { adminApi } from '@/api/admin.js'
const props = defineProps({ type: { type: String, required: true } })
const route = useRoute(); const router = useRouter(); const toast = inject('adminToast'); const items = ref([]); const loading = ref(true); const error = ref(''); const search = ref(''); const status = ref('')
const isWorks = computed(() => props.type === 'works'); const label = computed(() => isWorks.value ? 'Case studies' : 'Apps Lab'); const singular = computed(() => isWorks.value ? 'case study' : 'app')
const filtered = computed(() => items.value.filter((item) => `${item.title} ${item.description} ${(item.tags || item.categories || []).join(' ')}`.toLowerCase().includes(search.value.toLowerCase())))
async function load() { loading.value = true; error.value = ''; try { items.value = (await adminApi.list(props.type, status.value)).data } catch (e) { error.value = e.message } finally { loading.value = false } }
async function archive(item) { if (!confirm(`Archive ${item.title}?`)) return; try { await adminApi.archive(props.type, item.id); toast?.success(`${item.title} archived`); load() } catch (e) { toast?.error(e.message) } }
onMounted(load)

// Vue reuses this view instance when navigating between /admin/works and
// /admin/labs. Reload whenever the collection prop changes so the grid,
// loading state, filters, and API request all follow the active route.
watch(() => props.type, () => {
  search.value = ''
  status.value = ''
  load()
})
</script>
<template><section><div class="mb-7 flex flex-col justify-between gap-5 md:flex-row md:items-end"><div><p class="admin-eyebrow">Workspace</p><h1 class="admin-title">{{ label }}</h1><p class="mt-2 text-gray-500">Manage the content shown on the public portfolio.</p></div><button class="admin-button-primary" @click="router.push(`/admin/${props.type}/new`)">+ New {{ singular }}</button></div><div class="mb-6 flex flex-col gap-3 rounded-2xl border border-gray-200 bg-white p-3 sm:flex-row"><input v-model="search" class="admin-input flex-1" :placeholder="`Search ${label.toLowerCase()}…`" /><select v-model="status" class="admin-input sm:max-w-[180px]" @change="load"><option value="">All statuses</option><option value="published">Published</option><option value="draft">Draft</option><option value="archived">Archived</option></select><button class="admin-button-secondary" @click="load">Refresh</button></div><div v-if="error" class="mb-6 rounded-2xl border border-red-200 bg-red-50 p-4 text-sm text-red-700">{{ error }} <button class="ml-3 font-bold" @click="load">Retry</button></div><div v-if="loading" class="grid gap-6 md:grid-cols-2 xl:grid-cols-3"><div v-for="n in 3" :key="n" class="h-[390px] animate-pulse rounded-3xl bg-gray-200" /></div><div v-else-if="!filtered.length" class="admin-empty"><p class="font-bricolage text-2xl font-semibold">Nothing here yet.</p><p class="mt-2 text-gray-500">Create your first {{ singular }} to start building the collection.</p><button class="admin-button-primary mt-5" @click="router.push(`/admin/${props.type}/new`)">Create {{ singular }}</button></div><div v-else class="grid gap-6 md:grid-cols-2 xl:grid-cols-3"><article v-for="item in filtered" :key="item.id" class="group overflow-hidden rounded-3xl border border-gray-200 bg-white shadow-sm transition hover:-translate-y-1 hover:shadow-xl"><div class="relative flex aspect-[4/3] items-center justify-center overflow-hidden bg-[linear-gradient(135deg,#17A6E3,#132132)]"><div class="absolute inset-0 bg-black/10" /><div v-if="item.device !== 'browser'" class="relative h-[82%] aspect-[9/19] overflow-hidden rounded-[1.4rem] border-4 border-gray-800 bg-gray-900 shadow-2xl"><video v-if="item.previewVideoUrl || item.videoUrl" :src="item.previewVideoUrl || item.videoUrl" :poster="item.previewImageUrl || item.imageUrl" autoplay muted loop playsinline class="size-full object-cover" /><img v-else :src="item.previewImageUrl || item.imageUrl" :alt="item.title" class="size-full object-cover" /></div><div v-else class="relative aspect-video w-[82%] overflow-hidden rounded-xl border-4 border-gray-800 bg-gray-900 shadow-2xl"><video v-if="item.previewVideoUrl || item.videoUrl" :src="item.previewVideoUrl || item.videoUrl" :poster="item.previewImageUrl || item.imageUrl" autoplay muted loop playsinline class="size-full object-cover" /></div><span class="absolute left-4 top-4 rounded-full bg-black/50 px-3 py-1 text-xs font-semibold text-white">{{ item.status }}</span><button class="absolute right-4 top-4 rounded-full bg-white/90 px-3 py-1 text-xs font-bold text-gray-900 opacity-0 transition group-hover:opacity-100" @click="router.push(`/admin/${props.type}/${item.id}/edit`)">Edit</button></div><div class="p-5"><div class="flex justify-between gap-3 text-xs text-gray-400"><span>{{ isWorks ? (item.tags || []).join(', ') : item.category }}</span><span>{{ item.year }}</span></div><h2 class="mt-2 font-bricolage text-2xl font-bold">{{ item.title }}</h2><p class="mt-2 line-clamp-2 text-sm leading-6 text-gray-500">{{ item.description }}</p><div class="mt-5 flex items-center justify-between"><button class="text-sm font-semibold text-[#17A6E3]" @click="router.push(`/admin/${props.type}/${item.id}/edit`)">Edit content →</button><button class="text-xs text-red-500" @click="archive(item)">Archive</button></div></div></article></div></section></template>
